package com.ecole.gestion_scolaire.payroll.service;
import com.ecole.gestion_scolaire.common.exception.BusinessRuleException; import com.ecole.gestion_scolaire.identity.entity.UserAccount; import com.ecole.gestion_scolaire.identity.repository.UserAccountRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service public class PayrollCurrentUserService{private final UserAccountRepository users; public PayrollCurrentUserService(UserAccountRepository u){users=u;} public UserAccount get(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||a.getName()==null)throw new BusinessRuleException("Utilisateur courant introuvable");return users.findByUsername(a.getName()).orElseThrow(()->new BusinessRuleException("Utilisateur courant introuvable"));}}
